interface PaymentMethod {
    void authorize(int amountCents); // virtual by design: dispatch by runtime type
}

final class CardPayment implements PaymentMethod {
    @Override public void authorize(int amountCents) {
        System.out.println("card auth " + amountCents);
    }
}

final class WalletPayment implements PaymentMethod {
    @Override public void authorize(int amountCents) {
        System.out.println("wallet auth " + amountCents);
    }
}

class BillingService {
    // Overloading: caller convenience, bound at compile time.
    void checkout(PaymentMethod m, int amountCents) { m.authorize(amountCents); }
    void checkout(PaymentMethod m, double amountMajor) {
        checkout(m, (int) Math.round(amountMajor * 100));
    }

    void chargeAll(List<PaymentMethod> methods, int amountCents) {
        // One call site, N behaviors. Adding a new PaymentMethod
        // requires zero edits here. That is why runtime dispatch exists.
        for (PaymentMethod m : methods) m.authorize(amountCents);
    }
}

class Order {
    private final String id;
    Order(String id) { this.id = id; }

    // BUG: overloads instead of overrides. Missing Object signature.
    // Collections will use Object.equals, not this.
    public boolean equals(Order other) {
        return other != null && id.equals(other.id);
    }
    // Missing hashCode override as well.
}

class BaseParser {
    // Fragile hook: called from constructor.
    BaseParser() { parse(); }
    void parse() { /* base default */ }
}

class CsvParser extends BaseParser {
    private final String delimiter = ",";
    @Override void parse() {
        // Runs BEFORE delimiter is assigned when called via super().
        System.out.println("parsing with " + delimiter); // null on this path
    }
}
